CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_GENERATION_MONTH_SOURCE_REGION
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_GENERATION at grain Date.FiscalYear, Date.MonthName, Date.Quarter, EnergySource.SourceCategory, EnergySource.SourceName, PowerPlant.Region, Date.MonthNumber; covers 16.43% of weighted demand (2 clusters); est. 300,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       d1.QUARTER,
       e2.SOURCE_CATEGORY,
       e2.SOURCE_NAME,
       p3.REGION,
       d1.MONTH_NUMBER,
       SUM(f.CO2_EMISSIONS_KG) AS CO2_EMISSIONS_KG,
       SUM(f.CAPACITY_FACTOR_PCT) AS CAPACITY_FACTOR_PCT_SUM,
       COUNT(f.CAPACITY_FACTOR_PCT) AS CAPACITY_FACTOR_PCT_COUNT,
       MAX(f.CAPACITY_MW) AS CAPACITY_MW,
       SUM(f.FUEL_COST_PER_MWH) AS FUEL_COST_PER_MWH_SUM,
       COUNT(f.FUEL_COST_PER_MWH) AS FUEL_COST_PER_MWH_COUNT,
       SUM(f.GENERATED_MWH) AS GENERATED_MWH,
       COUNT(*) AS GENERATION_COUNT
FROM CORE.FCT_GENERATION f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_ENERGY_SOURCE e2 ON f.SOURCE_ID = e2.SOURCE_ID
JOIN CORE.DIM_POWER_PLANT p3 ON f.POWER_PLANT_ID = p3.POWER_PLANT_ID
GROUP BY ALL;
